###### alterações na estrutura e adicionar timestamps de criacao/alteracao

alter table cliente add data_criacao timestamp default current_timestamp;
alter table cliente add data_alteracao timestamp default current_timestamp;

alter table endereco add data_criacao timestamp default current_timestamp;
alter table endereco add data_alteracao timestamp default current_timestamp;

alter table ordem_servico add data_criacao timestamp default current_timestamp;
alter table ordem_servico add data_alteracao timestamp default current_timestamp;

alter table pagamento add data_criacao timestamp default current_timestamp, add valor decimal(16,4);
alter table pagamento add data_alteracao timestamp default current_timestamp;

alter table servico add data_criacao timestamp default current_timestamp;
alter table servico add data_alteracao timestamp default current_timestamp;

alter table servico_ordem_servico add data_criacao timestamp default current_timestamp;
alter table servico_ordem_servico add data_alteracao timestamp default current_timestamp;

alter table ordem_servico drop foreign key fk_ordem_cliente;
alter table ordem_servico drop column cliente_id;

drop table cliente_endereco;

alter table endereco add cliente_id int;
alter table endereco add constraint fk_endereco_cliente foreign key (cliente_id) references cliente(id);

alter table ordem_servico drop foreign key fk_ordem_pagamento;
alter table ordem_servico drop PAGAMENTO_ID;

alter table pagamento add ordem_servico_id int;
alter table pagamento add constraint fk_ordem_pagamento foreign key (ordem_servico_id) references ordem_servico(id);

alter table cliente modify contato text;

alter table ordem_servico add descricao text;

# data seed

-- ============================================================================
-- 1. SEED: CLIENTE (100 Registros)
-- Nomes fictícios criados a partir de matrizes de nomes e sobrenomes comuns
-- ============================================================================

-- ============================================================================
-- 2. SEED: ENDERECO (100 Registros)
-- Endereços referenciando vias principais e mapeados aos IDs dos Clientes
-- ============================================================================

-- ============================================================================
-- 3. SEED: SERVICO (100 Registros)
-- Catálogo de Produtos, Planos de Internet/Celular, Upgrades e Serviços de Campo
-- ============================================================================

-- ============================================================================
-- 4. SEED: ORDEM_SERVICO (100 Registros)
-- Descrições de serviço de campo, mapeando os 100 endereços anteriores
-- ============================================================================

-- ============================================================================
-- 5. SEED: PAGAMENTO (100 Registros)
-- Métodos de pagamento, descontos e ligações com as Ordens de Serviço
-- ============================================================================

-- ============================================================================
-- 6. SEED: SERVICO_ORDEM_SERVICO (200 Registros)
-- Associa exatamente 2 serviços para cada Ordem de Serviço (garantindo os 200)
-- ============================================================================
